      "review.grammarly.identifies.wordy.or.unclear.sentences": "Identifies wordy or unclear sentences and suggests improvements. Makes your writing more concise and easier to understand.",
      "review.grammarly.improves.word.choice.sentence.structure": "Improves word choice, sentence structure, and readability. Helps you develop a more professional writing style over time.",
      "review.grammarly.job.applications.perfect.resumes.cover": "Job Applications: Perfect resumes, cover letters, and LinkedIn profiles",
      "review.grammarly.key.features": "Key Features",
