      "review.grammarly.mobile.keyboard.for.ios.and": "Mobile keyboard for iOS and Android",
      "review.grammarly.not.ideal.for.technical.or": "Not ideal for technical or academic writing",
      "review.grammarly.our.recommendation": "Our Recommendation",
      "review.grammarly.plagiarism.checker.premium": "Plagiarism checker (Premium)",
      "review.grammarly.plagiarism.checker.requires.premium": "Plagiarism checker requires Premium",
      "review.grammarly.plan": "Plan",
